const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([86.428836, 35.879797]);
  const radius = 50000; // 50 km in meters
  const roi = point.buffer(radius);
  const startDate = '2024-08-01';
  const endDate = '2024-08-20';

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(roi)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  let size = collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${size}`);

  if (size === 0) {
    // Fallback to Landsat 9
    collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterDate(startDate, endDate)
      .filterBounds(roi)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    size = collection.size().getInfo();
    console.log(`Landsat 9 images found: ${size}`);

    if (size === 0) {
      console.log('No images found in date range.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Create water mask
  const image = collection.median().clip(roi);

  // Calculate MNDWI for water detection
  let waterIndex;
  if (collection.first().bandNames().contains('B3').getInfo()) {
    // Sentinel-2: MNDWI = (Green - SWIR) / (Green + SWIR)
    waterIndex = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
  } else {
    // Landsat: MNDWI = (Green - SWIR1) / (Green + SWIR1)
    waterIndex = image.normalizedDifference(['SR_B3', 'SR_B6']).rename('MNDWI');
  }

  const waterMask = waterIndex.gt(0.1); // Water threshold

  // 4. Check valid pixels
  const pixelCount = waterMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('MNDWI').getInfo();

  console.log(`Valid water pixels: ${pixelCount}`);

  if (pixelCount === null || pixelCount === 0) {
    console.log('No valid water pixels detected.');
    console.log('<answer>B</answer>');
    return;
  }

  // 5. Count distinct water bodies using connected components
  const waterBodies = waterMask.selfMask();
  const connected = waterBodies.connectedComponents({
    connectedness: ee.Kernel.square(1),
    maxSize: 256
  });

  // Get unique labels (each represents a separate water body)
  const labels = connected.select('labels');
  const uniqueLabels = labels.reduceRegion({
    reducer: ee.Reducer.countDistinct(),
    geometry: roi,
    scale: 3000,
    maxPixels: 1e9
  }).get('labels').getInfo();

  console.log(`Number of distinct water bodies detected: ${uniqueLabels}`);

  // 6. Validation & Final Answer
  if (uniqueLabels === null || uniqueLabels === undefined) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
  } else if (uniqueLabels > 3) {
    console.log('More than 3 lakes detected.');
    console.log('<answer>A</answer>');
  } else {
    console.log('3 or fewer lakes detected.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
